<?php

/**
 * Ouvertures au jour lues dans l'article de la gare (chantier « audit-gares-suite », 22/11/2026), pour les gares dont
 * l'ouverture n'était connue qu'à l'année ou déduite de la ligne. Fichier de données ajouté à la fin de
 * database/data/gares_corrections.php (même format : action « add », type « opening », source « correction »).
 *
 * Règles de sélection (rapport storage/app/reports/agents/aprem-2111/audit-gares-suite.md) :
 *  - la gare VFF est liée à l'article par son élément Wikidata et son nom correspond au titre de l'article ;
 *  - la date vient de « mise en service » de l'infobox, sinon d'une phrase « la gare est mise en service le … » ;
 *  - même année que la date VFF (Wikidata ou déduite) : le jour précise l'année ;
 *  - année différente : seulement quand VFF a déduit l'année de la ligne, que la date est avant 1940 et que l'article la
 *    dit dans une phrase sur la gare elle-même ;
 *  - (deuxième passe, fin du fichier) conflits avec Wikidata ou OpenHistoricalMap : article antérieur d'au moins 3 ans et phrase sur
 *    la gare elle-même ; remplacements : phrase sur la gare ou la section où elle se trouve (PK vérifié dans vff) ;
 *  - jamais une date qui contredit une source non déduite (Wikidata, OpenHistoricalMap), une réouverture, une gare
 *    récente, une section ou une ligne entière (liste au rapport).
 *
 * Pas de tiret long dans les textes (consigne éditoriale).
 *
 * @return list<array<string, mixed>>
 */
$wp = fn (string $title, int $oldid) => 'https://fr.wikipedia.org/w/index.php?title='.rawurlencode(str_replace(' ', '_', $title)).'&oldid='.$oldid;

return array_map(fn (array $g) => [
    'station' => ['name' => $g[0], 'wikidata' => $g[1]],
    'action' => 'add',
    'type' => 'opening',
    'date' => $g[4],
    'precision' => 'day',
    'source_url' => $wp($g[2], $g[3]),
    'quote' => $g[5],
    'reason' => 'ouverture de la gare au jour d\'après l\'article de la gare ; '.$g[6],
], [
